package com.yongzhe.localserver;
import org.json.JSONArray;
import org.json.JSONObject;

/** Local gameplay catalog. DTOs follow the Cocos client's ApiAfkRepository mapper. */
public final class GameContent {
    private GameContent() {}
    public static JSONArray maps(){JSONArray a=new JSONArray();try{a.put(map("map_1","勇者平原",1,1,1,4));a.put(map("map_2","迷雾森林",5,2,5,8));a.put(map("map_3","遗迹峡谷",10,3,10,15));}catch(Exception ignored){}return a;}
    public static JSONArray instanceMaps(){JSONArray a=new JSONArray();try{a.put(instanceMap("instance_1","试炼副本",1));}catch(Exception ignored){}return a;}
    public static JSONObject instanceLevels(String id){JSONObject out=new JSONObject();try{JSONObject m=instanceMap(id,"试炼副本",1);JSONArray levels=new JSONArray();levels.put(new JSONObject().put("id",id+"_lv1").put("level",1).put("instanceMapId",id).put("instanceMapName",m.optString("name")).put("minLevel",1).put("maxLevel",10).put("levelInRange",true).put("canEnter",true).put("cleared",false).put("canSweep",false).put("enterGoldCost",0).put("battleTimeMinutes",10));out.put("map",m);out.put("levels",levels);out.put("characterLevel",1);}catch(Exception ignored){}return out;}
    public static String mapName(String id){JSONArray a=maps();for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m!=null&&id.equals(m.optString("id")))return m.optString("name");}return id;}
    private static JSONObject map(String id,String name,int minLevel,int order,int monsterMin,int monsterMax)throws Exception{JSONObject o=new JSONObject();o.put("id",id);o.put("name",name);o.put("description",name);o.put("kind","upgrade");o.put("minLevel",minLevel);o.put("monsterLevelMin",monsterMin);o.put("monsterLevelMax",monsterMax);o.put("monsterCount",2);o.put("isBossMap",false);o.put("iconColor",new JSONObject().put("r",80).put("g",145).put("b",110).put("a",255));o.put("tileManifest","map/"+id+"/tile.json");o.put("miniImg","");o.put("order",order);o.put("enterGoldCost",0);o.put("canEnter",true);o.put("levelMatched",true);o.put("maxLevel",99);return o;}
    private static JSONObject instanceMap(String id,String name,int minLevel)throws Exception{JSONObject o=map(id,name,minLevel,1,minLevel,minLevel+5);o.put("kind","instance");o.put("entryType","ticket");o.put("toolsId","");o.put("toolsName","");o.put("ticketOwned",0);o.put("dailyMax",3);o.put("dailyRemain",3);o.put("battleTimeMinutes",10);o.put("tileManifest","fmap/"+id+"/tile.json");return o;}
    public static JSONArray monsters(String mapId){JSONArray a=new JSONArray();try{if("map_2".equals(mapId)){a.put(mon("m201",mapId,"森林狼",6,70,12,6));a.put(mon("m202",mapId,"树妖",8,100,16,9));}else if("map_3".equals(mapId)){a.put(mon("m301",mapId,"遗迹守卫",11,160,24,15));a.put(mon("m302",mapId,"峡谷领主",15,260,35,24));}else{a.put(mon("m101",mapId,"史莱姆",1,30,5,2));a.put(mon("m102",mapId,"野狼",3,50,8,4));}}catch(Exception ignored){}return a;}
    private static JSONObject mon(String id,String mapId,String name,int lv,int hp,int atk,int def)throws Exception{JSONObject o=new JSONObject();o.put("id",id);o.put("mapId",mapId);o.put("name",name);o.put("level",lv);o.put("hp",hp);o.put("maxHp",hp);o.put("atk",atk);o.put("attackMin",Math.max(1,atk-2));o.put("attackMax",atk+2);o.put("def",def);o.put("defense",def);o.put("exp",lv*8);o.put("gold",lv*3);o.put("speed",1);o.put("moveSpeed",1);o.put("attackSpeed",1);o.put("attackRate",100);o.put("viewRange",5);o.put("iconColor",new JSONObject().put("r",150).put("g",150).put("b",150).put("a",255));o.put("iconLabel",name.substring(0,1));o.put("dropGroups",new JSONArray());return o;}
    public static JSONObject monster(String mapId,String monsterId){JSONArray a=monsters(mapId);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&monsterId.equals(o.optString("id")))return o;}return a.optJSONObject(0)==null?new JSONObject():a.optJSONObject(0);}
    public static JSONArray shop(){JSONArray a=new JSONArray();try{a.put(shopItem(1001,"小型生命药水",100,"gold",20));a.put(shopItem(1002,"小型魔法药水",100,"gold",20));a.put(shopItem(2001,"回城卷轴",500,"gold",1));}catch(Exception ignored){}return a;}
    private static JSONObject shopItem(int id,String name,long price,String currency,int count)throws Exception{JSONObject o=new JSONObject();o.put("id",String.valueOf(id));o.put("itemId",id);o.put("name",name);o.put("price",price);o.put("currency",currency);o.put("count",count);o.put("enabled",true);return o;}
}
